 public List<IntegrationPermissionProbeResultPo> toResultPos(PermissionProbeResult v){var out=new ArrayList<IntegrationPermissionProbeResultPo>();v.capabilityResults().forEach((cap,status)->{var p=new IntegrationPermissionProbeResultPo();p.setTenantId(v.tenantId());p.setProbeResultId(v.probeId()+"-"+cap.name().toLowerCase());p.setProbeId(v.probeId());p.setCapabilityCode(cap.name());p.setResultStatus(status.name());p.setObservedAt(v.completedAt());out.add(p);});return out;}
 public PermissionProbeResult probe(IntegrationPermissionProbeRunPo run,List<IntegrationPermissionProbeResultPo> rows){var values=new EnumMap<IntegrationPermissionCapability,PermissionProbeResultStatus>(IntegrationPermissionCapability.class);for(var row:rows)values.put(IntegrationPermissionCapability.valueOf(row.getCapabilityCode()),PermissionProbeResultStatus.valueOf(row.getResultStatus()));return new PermissionProbeResult(run.getTenantId(),run.getProbeId(),run.getConnectionId(),run.getPrincipalId(),run.getMappingId(),ProjectMappingStatus.valueOf(run.getOverallStatus()),values,readList(run.getElevatedPermissionsJson()),run.getProviderResponseSummary(),run.getStartedAt(),run.getCompletedAt(),run.getCorrelationId());}
