 private Map<String,String> readStringMap(String v){return readMap(v);}
 private String write(Object v){try{return json.writeValueAsString(v);}catch(Exception e){throw new IllegalStateException(e);}} @SuppressWarnings("unchecked") private Map<String,String> readMap(String v){try{return v==null?Map.of():json.readValue(v,Map.class);}catch(Exception e){return Map.of();}} @SuppressWarnings("unchecked") private List<String> readList(String v){try{return v==null?List.of():json.readValue(v,List.class);}catch(Exception e){return List.of();}} private List<IntegrationOperation> readOperations(String v){return readList(v).stream().map(IntegrationOperation::valueOf).toList();}
